function [masked_data,varargout] = mask_cut(cut_data,varargin)
masked_data = cut_data;
for i=1:numel(varargin)
    mask_vert = varargin{i};
    if isempty(mask_vert)
        fh=plot(masked_data);liny; lz 0 2;
        [ms,~,mask_vert] = draw_mask(fh);
    else
        ms = draw_mask(masked_data,'mask',mask_vert);
    end
    masked_data = mask(masked_data,ms);
    varargout{i} = mask_vert';
    plot(masked_data);liny; lz 0 0.5; keep_figure;
end
end


